  "implementation": "def solve(case):
    if 'nodes' not in case or 'required_symbols' not in case:
        raise ValueError("Missing required fields: nodes, required_symbols")
    nodes = case['nodes']
    required_symbols = set(case['required_symbols'])
    node_map = {}
    for n in nodes:
        nid = n.get('id')
        if not nid:
            raise ValueError("Node missing id")
        node_map[nid] = n
    root = None
    for nid, n in node_map.items():
        if n.get('parent') is None:
            if root is not None:
                raise ValueError("Multiple roots")
            root = nid
    if root is None:
        raise ValueError("No root")
    children = {nid: [] for nid in node_map}
    for nid, n in node_map.items():
        pid = n.get('parent')
        if pid is not None:
            if pid not in node_map:
                raise ValueError(f"Parent {pid} not found")
            children[pid].append(nid)
    symbol_present = {}
    for n in nodes:
        sym = n['symbol']
        symbol_present.setdefault(sym, set()).add(n['id'])
    for sym in required_symbols:
        if sym not in symbol_present:
            raise ValueError(f"Required symbol '{sym}' not present in tree")
    retained = set(node_map.keys())
    removed = set()
    removal_order = []
    def check_required_preserved(to_remove):
        remaining_symbols = set()
        for nid in retained - to_remove:
            remaining_symbols.add(node_map[nid]['symbol'])
        return required_symbols.issubset(remaining_symbols)
    import heapq
    heap = []
    for nid in retained:
        n = node_map[nid]
        if n.get('removable', False) and n['symbol'] not in required_symbols:
            if not any(cid in retained for cid in children[nid]):
                heapq.heappush(heap, (-n.get('depth', 0), nid, nid))
    while heap:
        neg_depth, tie_id, nid = heapq.heappop(heap)
        if nid not in retained:
            continue
        if any(cid in retained for cid in children[nid]):
            continue
        to_remove = {nid}
        if not check_required_preserved(to_remove):
            continue
        for rid in to_remove:
            retained.discard(rid)
            removed.add(rid)
        removal_order.append(nid)
        parent_id = node_map[nid].get('parent')
        if parent_id is not None and parent_id in retained:
            parent = node_map[parent_id]
            if parent.get('removable', False) and parent['symbol'] not in required_symbols:
                if not any(cid in retained for cid in children[parent_id]):
                    heapq.heappush(heap, (-parent.get('depth', 0), parent_id, parent_id))
    return {
        "removed_node_ids": removal_order,
        "retained_node_ids": sorted(retained)
    }"
}
